package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public final class ConversationReliabilityChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("conversation reliability "+n);}interface Action{void run()throws Exception;}static void rejects(Action a)throws Exception{try{a.run();throw new AssertionError("expected rejection "+n);}catch(IOException|IllegalArgumentException|JSONException expected){n++;}}
 public static int run(Context base,String path)throws Exception{File root=new File(path);root.mkdirs();Context c=new ContextWrapper(base){public File getFilesDir(){return root;}public Context getApplicationContext(){return this;}};long now=System.currentTimeMillis();String a="a".repeat(64),b="b".repeat(64);
 c.getSharedPreferences("conversation-display",0).edit().clear().commit();ok(ConversationReliability.settings(c).getString("answerStyle").equals("short"));ok(ConversationReliability.settings(c).getBoolean("streaming"));JSONObject config=new JSONObject().put("answerStyle","detailed").put("glassChars",300).put("streaming",false);ok(ConversationReliability.settings(c,config).getInt("glassChars")==300);ok(!ConversationReliability.settings(c).getBoolean("streaming"));rejects(()->ConversationReliability.settings(c,new JSONObject(config.toString()).put("glassChars",1)));rejects(()->ConversationReliability.settings(c,new JSONObject(config.toString()).put("answerStyle","arbitrary")));
 JSONArray active=new JSONArray().put(new JSONObject().put("key",a).put("requestState","RUNNING"));ConversationReliability.partial(a,"RUNNING",new JSONObject().put("partial","first").put("partialSequence",2),now);ConversationReliability.partial(a,"RUNNING",new JSONObject().put("partial","stale").put("partialSequence",1),now);ok(ConversationReliability.partials(active,now).getJSONObject(0).getString("text").equals("first"));ok(ConversationReliability.partials(active,now+120001).length()==0);ConversationReliability.partial(a,"RUNNING",new JSONObject().put("partial","again").put("partialSequence",3),now);ConversationReliability.partial(a,"STOPPED",new JSONObject(),now);ok(ConversationReliability.partials(active,now).length()==0);rejects(()->ConversationReliability.partial(a,"RUNNING",new JSONObject().put("partial","x".repeat(12001)).put("partialSequence",4),now));rejects(()->ConversationReliability.partial("bad","RUNNING",new JSONObject(),now));
 JSONArray history=new JSONArray();for(int i=0;i<45;i++){String id=String.format("%064x",i+1);history.put(new JSONObject().put("requestId",id).put("kind","ユーザー").put("time",now+i).put("message","question "+i)).put(new JSONObject().put("requestId",id).put("kind","Gemini").put("time",now+i+1).put("message","answer "+i));}JSONObject first=ConversationReliability.page(history,20,"","");ok(first.getJSONArray("items").length()==40);ok(first.getBoolean("hasMore"));JSONObject second=ConversationReliability.page(history,20,first.getString("before"),first.getString("revision"));ok(second.getJSONArray("items").length()==40);ok(!second.getJSONArray("items").toString().contains("question 44"));JSONObject third=ConversationReliability.page(history,20,second.getString("before"),second.getString("revision"));ok(third.getJSONArray("items").length()==10);ok(!third.getBoolean("hasMore"));rejects(()->ConversationReliability.page(history,20,a,"wrong"));rejects(()->ConversationReliability.page(history,100,"",""));ok(ConversationReliability.page(new JSONArray(),20,"","").getJSONArray("items").length()==0);
 ConversationUpgradeChecks.setup(c,ConversationUpgradeChecks.row(a,"private question"),ConversationUpgradeChecks.row(b,"kept pending"));MainActivity.ackTrackedWebCommand(c,a);JSONObject reconcile=ConversationReliability.reconcile(c);ok(!reconcile.getBoolean("automaticallyResent"));ok(ConversationContinuation.ledger(c).getJSONObject(0).getString("requestState").equals("UNCONFIRMED"));ok(MainActivity.hasQueuedWebCommand(c,b));ok(!ConversationReliability.reconcile(c).getBoolean("automaticallyResent"));
 MainActivity owner=ReliabilityChecks.owner(c);JSONObject diagnostic=ConversationReliability.diagnostics(owner);ok(!diagnostic.toString().contains("private question"));ok(!diagnostic.toString().contains(a));ok(!diagnostic.toString().contains(b));ok(diagnostic.getLong("phoneVersion")==owner.getPackageManager().getPackageInfo(owner.getPackageName(),0).getLongVersionCode());ok(diagnostic.getJSONObject("requestStateCounts").getInt("UNCONFIRMED")==1);
 File photo=new File(RecorderPhotoStore.root(c),"synthetic.bin");try(FileOutputStream out=new FileOutputStream(photo)){out.write(new byte[123]);}ok(ConversationReliability.storage(owner).getLong("photoBytes")==123);ok(ConversationReliability.failure("RATE_LIMIT").contains("上限"));ok(ConversationReliability.failure("NETWORK").contains("通信"));ok(ConversationReliability.failure("MODEL_ERROR").contains("モデル"));
 java.lang.reflect.Method memory=MainActivity.class.getDeclaredMethod("conversationMemoryFile");memory.setAccessible(true);File file=(File)memory.invoke(owner);JSONObject ra=new JSONObject().put("requestId",a).put("kind","ユーザー").put("time",now).put("message","same text"),rb=new JSONObject(ra.toString()).put("requestId",b);try(FileOutputStream out=new FileOutputStream(file)){out.write((ra+"\n"+rb+"\n").getBytes("UTF-8"));}JSONArray groups=ConversationCollections.group(owner.webHistory());JSONObject selected=groups.getJSONObject(0);JSONObject deletion=new JSONObject().put("items",new JSONArray().put(new JSONObject().put("key",a).put("revision",selected.getString("revision"))));rejects(()->owner.pruneWebConversation(new JSONObject(deletion.toString()).put("items",new JSONArray().put(new JSONObject().put("key",a).put("revision","old")))));c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",new JSONArray().put(ConversationUpgradeChecks.row(a,"private question").put("requestState","RUNNING")).toString()).commit();rejects(()->owner.pruneWebConversation(deletion));c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",new JSONArray().put(ConversationUpgradeChecks.row(a,"private question").put("requestState","ANSWERED")).toString()).commit();ok(owner.pruneWebConversation(deletion).getInt("removedRows")==1);ok(owner.webHistory().length()==1);ok(owner.webHistory().getJSONObject(0).getString("requestId").equals(b));
 String token="d".repeat(64);c.getSharedPreferences("loki_web_console",0).edit().putString("sessions",new JSONArray().put(new JSONObject().put("hash",RecorderPhotoStore.hash(token.getBytes("UTF-8"))).put("scope","read").put("expires",now+600000)).toString()).commit();for(String route:new String[]{"conversation-settings","conversation-reconcile","conversation-prune"}){ReliabilityChecks.SocketFixture socket=new ReliabilityChecks.SocketFixture();LokiWebConsole.handle(owner,socket,"POST /web/api/"+route+" HTTP/1.1","{}",token,"","fixture");ok(socket.text().startsWith("HTTP/1.1 403"));}
 c.getSharedPreferences("conversation-display",0).edit().clear().commit();c.getSharedPreferences("phone_secretary",0).edit().clear().commit();c.getSharedPreferences("loki_web_console",0).edit().clear().commit();return n;
 }
}
